#!/usr/bin/env bash
# CHAPITRE « Les styles » + corrections révélées en l'écrivant :
#   - réglage de style, texte d'accueil et pages de contenu : écriture réservée aux admins
#     (n'importe quel membre connecté pouvait les modifier en appelant la procédure) ;
#   - valider un média / changer sa description : admin, ou éditeur de l'espace de groupe ;
#   - média-texte sans colonnes au-delà de 62rem sur une base sans réglage enregistré ;
#   - laboratoire : le ratio enregistré reprend sa place ; tailwind.config.ts (ignoré) supprimé.
# Prérequis : apply-emails-membres-club.sh.
# Usage (racine du repo) : bash apply-styles.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/front/styles.mdx" 2>/dev/null | grep -qF "title: \"Les styles\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "clubEmail" "prisma/schema.prisma" 2>/dev/null || { echo "❌ lancer d'abord apply-emails-membres-club.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/donnees/modeliser-avec-prisma.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/src/app/api/admin/revalidate-style/route.ts" "apps/web/src/app/globals.css" "apps/web/src/features/design-lab/BlockStyleLab.tsx" "apps/web/src/features/theme/ThemeToggle.tsx" "packages/backend/src/modules/homeHero/router.ts" "packages/backend/src/modules/media/router.ts" "packages/backend/src/modules/sitePages/router.ts" "packages/backend/src/modules/siteStyle/router.ts")
CREATED=("apps/web/content/docs/dev/front/styles.mdx")
restore(){ [ -n "${DELETED+x}" ] && { git reset -q -- "${DELETED[@]}" 2>/dev/null; git checkout -q -- "${DELETED[@]}" 2>/dev/null; }; git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les styles\"" "apps/web/content/docs/dev/front/styles.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/front"
base64 -d > "apps/web/content/docs/dev/front/styles.mdx" <<'B64'
