trap - ERR

DELETED=("apps/web/tailwind.config.ts")
for f in "${DELETED[@]}"; do
  if [ -f "$f" ] && ! git diff --quiet HEAD -- "$f" 2>/dev/null; then
    mkdir -p "docs-sauvegarde/$(dirname "$f")"; cp "$f" "docs-sauvegarde/$f"
    echo "  ⚠ modifications locales sauvegardées : docs-sauvegarde/$f"
  fi
done
git rm -q -f --ignore-unmatch -- "${DELETED[@]}"
echo "  tailwind.config.ts supprimé"
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git add -A -- "${DELETED[@]}" 2>/dev/null || true
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
styles: chapitre « Les styles » ; écritures du style, de l'accueil et des pages réservées aux admins

- siteStyle.save/saveLimits, homeHero.save, sitePage.save : isAdmin (étaient
  ouvertes à tout membre connecté) ; /api/admin/revalidate-style : admin.
- media.setStatus / updateDescription : admin, ou éditeur de l'espace de
  groupe concerné (même règle que la corbeille).
- globals.css : valeurs par défaut de --akfc-media-col / --akfc-text-col
  (sans réglage enregistré, le média-texte n'avait plus de colonnes au-delà
  de 62rem) ; sélecteur orphelin .cropper-container retiré.
- Laboratoire : le ratio enregistré reprend sa place sur le curseur.
- tailwind.config.ts supprimé (ignoré par Tailwind 4).
- Doc : chapitre 3.3 « Les styles » ; raccord du chapitre Données ; sommaire.

